mapper.select:
select cc.id, uc.id, cc.class_name as className, o.class_key as classKey, uc.unit_name as unitName, o.unit_key as unitKey, o.total_count as count, 'base' as type
from erp_order o
    JOIN erp_class_code cc
on o.class_key = cc.class_key
    JOIN erp_unit_code uc on o.unit_key =uc.unit_key
where user_code = #{userCode}
  AND yy= #{yy}
  AND mm = #{mm}
UNION ALL
select cc.id, uc.id, cc.class_name as className, r.class_key as classKey, uc.unit_name as unitName, r.unit_key as unitKey, r.count as count, r.reorder_type as type
from erp_reorder r
    JOIN erp_class_code cc
on r.class_key = cc.class_key
    JOIN erp_unit_code uc on r.unit_key =uc.unit_key
where user_code = #{userCode}
  AND yy= #{yy}
  AND mm = #{mm}
  AND confirmed = 'checked'

ORDER BY cc.id, uc.id

SELECT dead_line_at
FROM erp_order_deadline
where center_code = #{centerCode}

SELECT *
FROM erp_order
WHERE center_code = #{centerCode}
  AND user_code = #{userCode}
  AND yy = #{yy}
  ANd mm = #{mm}

