  AND user_code = #{userCode}
  AND yy = #{yy}
  AND mm = #{mm}

update.foreach:
UPDATE erp_class_fee_map
SET fee = #{item.fee}
WHERE class_key = #{item.classKey}
AND center_code = #{item.centerCode}
AND (
(unit_key IS NULL AND #{item.unitKey} IS NULL)
OR unit_key = #{item.unitKey}
)

mapper.update:
UPDATE erp_reorder
SET confirmed = 'user_cancel'
where id = #{id}

mapper.select:
SELECT base.class_key                                                                       AS classKey,
       c.class_name                                                                         AS className,
       base.unit_key                                                                        AS unitKey,
       u.unit_name                                                                          AS unitName,
       COALESCE(t.assign_count, 0) + COALESCE(a.add_count, 0)                              AS scheduleCount,
       COALESCE(r.return_count, 0)                                                          AS currentReturnCount,
       CASE
           WHEN COALESCE(t.assign_count, 0) + COALESCE(a.add_count, 0) - COALESCE(r.return_count, 0) > 0
               THEN COALESCE(t.assign_count, 0) + COALESCE(a.add_count, 0) - COALESCE(r.return_count, 0)
           ELSE 0
           END                                                                              AS maxReturnCount
FROM (SELECT class_key, unit_key
      FROM erp_order
      WHERE center_code = #{centerCode}
        AND user_code = #{userCode}
        AND yy = #{yy}
        AND mm = #{mm}
      UNION
      SELECT class_key, unit_key
      FROM erp_reorder
      WHERE center_code = #{centerCode}
        AND user_code = #{userCode}
        AND yy = #{yy}
        AND mm = #{mm}
        AND reorder_type = 'ADD'
        AND confirmed = 'checked') base
         JOIN erp_class_code c ON base.class_key = c.class_key
         JOIN erp_unit_code u ON base.unit_key = u.unit_key
         LEFT JOIN (SELECT tt.class_key,
                           tt.unit_key,
                           COUNT(ta.student_id) AS assign_count
                    FROM erp_time_table tt
                             JOIN erp_time_table_assign ta ON tt.time_table_key = ta.time_table_key
                    WHERE tt.center_code = #{centerCode}
                      AND tt.user_code = #{userCode}
                      AND tt.yy = #{yy}
                      AND tt.mm = #{mm}
                    GROUP BY tt.class_key, tt.unit_key) t
                   ON t.class_key = base.class_key AND t.unit_key = base.unit_key
         LEFT JOIN (SELECT class_key,
                           unit_key,
                           SUM(count) AS add_count
                    FROM erp_reorder
                    WHERE center_code = #{centerCode}
                      AND user_code = #{userCode}
                      AND yy = #{yy}
                      AND mm = #{mm}
                      AND reorder_type = 'ADD'
                      AND confirmed = 'checked'
                    GROUP BY class_key, unit_key) a
                   ON a.class_key = base.class_key AND a.unit_key = base.unit_key
         LEFT JOIN (SELECT class_key,
                           unit_key,
                           SUM(count) AS return_count
                    FROM erp_reorder
                    WHERE center_code = #{centerCode}
                      AND user_code = #{userCode}
                      AND yy = #{yy}
                      AND mm = #{mm}
                      AND reorder_type = 'RETURN'
                      AND confirmed != 'user_cancel'
                    GROUP BY class_key, unit_key) r
                   ON r.class_key = base.class_key AND r.unit_key = base.unit_key

SELECT
    (SELECT COUNT(ta.student_id)
     FROM erp_time_table t
              JOIN erp_time_table_assign ta ON t.time_table_key = ta.time_table_key
     WHERE t.center_code = #{centerCode}
       AND t.user_code = #{userCode}
       AND t.yy = #{yy}
       AND t.mm = #{mm}
       AND t.class_key = #{classKey}
       AND t.unit_key = #{unitKey})
    +
    COALESCE(
        (SELECT SUM(count)
         FROM erp_reorder
         WHERE center_code = #{centerCode}
           AND user_code = #{userCode}
           AND yy = #{yy}
           AND mm = #{mm}
           AND class_key = #{classKey}
           AND unit_key = #{unitKey}
           AND reorder_type = 'ADD'
           AND confirmed = 'checked'),
        0
    )

SELECT COALESCE(SUM(count), 0)
FROM erp_reorder
WHERE center_code = #{centerCode}
  AND user_code = #{userCode}
  AND yy = #{yy}
  AND mm = #{mm}
  AND class_key = #{classKey}
  AND unit_key = #{unitKey}
  AND reorder_type = 'RETURN'
  AND confirmed != 'user_cancel'
